def _build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_streaks_result(
    backtest_records: tuple[dict[str, object], ...],
    scorecards: tuple[dict[str, object], ...],
    baseline_splits: tuple[int, ...],
    min_evaluated_delta: int,
    min_hit_rate_drop: tuple[int, int],
    regression_limit: int,
    min_consecutive_splits: int,
    regression_streak_limit: int,
) -> dict[str, object]:
    """Connect per-split regression hits into per-identity streaks.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_streaks`.
    Each requested split position reruns
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regressions_result`
    on the same frozen backtest records and scorecards with
    ``baseline_cutoffs`` set to that position's value, so the
    position's kept regression set, thresholds and
    ``regression_limit`` enforcement are exactly the single-split
    query's. An identity present in the regression records of two
    adjacent requested positions belongs to one run; an identity
    absent from any requested position ends its run there. Only
    runs of at least ``min_consecutive_splits`` positions are
    kept, and only each identity's longest run survives, ties
    broken by the smaller start split and then the larger worst
    drop.

    Each kept record is a fresh dict with keys ordered ``identity,
    start_baseline_cutoffs, end_baseline_cutoffs, split_count,
    first_regression_cutoff, worst_rate_drop``: the run's first
    and last requested split values, the run length in positions,
    the smallest ``first_regression_cutoff`` over the run and the
    largest ``rate_drop`` over the run as a reduced
    ``(numerator, denominator)`` integer tuple (fractions compared
    by integer cross-multiplication, never dividing). Records sort
    by ``split_count`` descending, then ``worst_rate_drop``
    descending, then the identity in Unicode code point order. The
    complete qualifying set is built before
    ``regression_streak_limit`` is enforced, so an over-limit
    query raises :class:`ValueError` without truncating.
    ``totals`` is a fresh dict ordered ``identities, streaks,
    regressing_splits``: the kept identity count, the kept streak
    count and the number of distinct requested split positions
    covered by the kept streaks; no qualifying streak yields an
    empty tuple and three zeros. Every record is built fresh and
    shares no mutable object with the backtest records or the
    scorecards.
    """
    per_split: list[dict[object, dict[str, object]]] = []
    for split in baseline_splits:
        point = BranchStore._build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regressions_result(
            backtest_records,
            scorecards,
            split,
            min_evaluated_delta,
            min_hit_rate_drop,
            regression_limit,
        )
        per_identity: dict[object, dict[str, object]] = {}
        for record in point["regressions"]:
            per_identity[record["identity"]] = record
        per_split.append(per_identity)

    active: dict[object, dict[str, object]] = {}
    started: list[dict[str, object]] = []
    for index, per_identity in enumerate(per_split):
        for identity, record in per_identity.items():
            run = active.get(identity)
            if run is None:
                run = {
                    "identity": identity,
                    "start_index": index,
                    "records": [],
                }
                active[identity] = run
                started.append(run)
            run["records"].append(record)
        for identity in list(active):
            if identity not in per_identity:
                del active[identity]

    def drop_exceeds(
        left: tuple[int, int], right: tuple[int, int]
    ) -> bool:
        # Both drops have positive denominators, so integer
        # cross-multiplication orders them without dividing.
        return left[0] * right[1] > right[0] * left[1]

    best_by_identity: dict[object, dict[str, object]] = {}
    for run in started:
        records = run["records"]
        if len(records) < min_consecutive_splits:
            continue
        worst_rate_drop = records[0]["rate_drop"]
        first_regression_cutoff = records[0][
            "first_regression_cutoff"
        ]
        for record in records[1:]:
            if drop_exceeds(record["rate_drop"], worst_rate_drop):
                worst_rate_drop = record["rate_drop"]
            if (
                record["first_regression_cutoff"]
                < first_regression_cutoff
            ):
                first_regression_cutoff = record[
                    "first_regression_cutoff"
                ]
        streak = {
            "identity": run["identity"],
            "start_baseline_cutoffs": baseline_splits[
                run["start_index"]
            ],
            "end_baseline_cutoffs": baseline_splits[
                run["start_index"] + len(records) - 1
            ],
            "split_count": len(records),
            "first_regression_cutoff": first_regression_cutoff,
            "worst_rate_drop": worst_rate_drop,
        }
        identity = run["identity"]
        incumbent = best_by_identity.get(identity)
        if incumbent is None:
            best_by_identity[identity] = streak
            continue
        if streak["split_count"] != incumbent["split_count"]:
            if streak["split_count"] > incumbent["split_count"]:
                best_by_identity[identity] = streak
            continue
        if (
            streak["start_baseline_cutoffs"]
            != incumbent["start_baseline_cutoffs"]
        ):
            if (
                streak["start_baseline_cutoffs"]
                < incumbent["start_baseline_cutoffs"]
            ):
                best_by_identity[identity] = streak
            continue
        if drop_exceeds(
            streak["worst_rate_drop"], incumbent["worst_rate_drop"]
        ):
            best_by_identity[identity] = streak

    streaks = list(best_by_identity.values())

    def compare_streaks(
        left: dict[str, object], right: dict[str, object]
    ) -> int:
        if left["split_count"] != right["split_count"]:
            return (
                -1
                if left["split_count"] > right["split_count"]
                else 1
            )
        if drop_exceeds(
            left["worst_rate_drop"], right["worst_rate_drop"]
        ):
            return -1
        if drop_exceeds(
            right["worst_rate_drop"], left["worst_rate_drop"]
        ):
            return 1
        left_key = BranchStore._lifetime_identity_unicode_key(
            left["identity"]
        )
        right_key = BranchStore._lifetime_identity_unicode_key(
            right["identity"]
        )
        if left_key < right_key:
            return -1
        if left_key > right_key:
            return 1
        return 0

    streaks.sort(key=functools.cmp_to_key(compare_streaks))

    if len(streaks) > regression_streak_limit:
        raise ValueError(
            f"lifetime churn drift wave prediction scorecard "
            f"regression streak limit exceeded: {len(streaks)} "
            f"streaks, limit is {regression_streak_limit}"
        )

    split_seen: set[object] = set()
    totals = {"identities": 0, "streaks": 0, "regressing_splits": 0}
    for streak in streaks:
        totals["identities"] += 1
        totals["streaks"] += 1
        for index in range(
            baseline_splits.index(streak["start_baseline_cutoffs"]),
            baseline_splits.index(streak["end_baseline_cutoffs"]) + 1,
        ):
            split_seen.add(baseline_splits[index])
    totals["regressing_splits"] = len(split_seen)
    return {"streaks": tuple(streaks), "totals": totals}

@staticmethod
def _build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_waves_result(
    streaks: tuple[dict[str, object], ...],
    baseline_splits: tuple[int, ...],
    min_active_regressions: int,
    regression_wave_limit: int,
) -> dict[str, object]:
    """Group positions where enough kept streaks stay active.

    Used only by
    :meth:`lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_waves`.
    The streaks are the complete, already-bounded ``streaks`` tuple
    of
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_streaks_result`
    in its final order and ``baseline_splits`` the validated
    requested positions. Each requested position counts the
    distinct identities whose kept streak covers it, listed in that
    streak order, and maximal runs of adjacent requested positions
    reaching ``min_active_regressions`` active identities form the
    waves -- unrequested integer positions do not break adjacency,
    while a requested position below the threshold ends the run.
    ``regression_wave_limit`` bounds the final wave count, raising
    :class:`ValueError` rather than truncating. Every wave and
    point dict is built fresh and shares no mutable object with the
    streak records.
    """
    position_of = {
        split: index for index, split in enumerate(baseline_splits)
    }
    coverage: list[list[object]] = [[] for _ in baseline_splits]
    for streak in streaks:
        identity = streak["identity"]
        start = position_of[streak["start_baseline_cutoffs"]]
        end = position_of[streak["end_baseline_cutoffs"]]
        for index in range(start, end + 1):
            coverage[index].append(identity)

    waves: list[dict[str, object]] = []
    current: list[dict[str, object]] = []
    for index, split in enumerate(baseline_splits):
        identities: list[object] = []
        seen: set[object] = set()
        for identity in coverage[index]:
            if identity in seen:
                continue
            seen.add(identity)
            identities.append(identity)
        if len(identities) >= min_active_regressions:
            current.append(
                {
                    "baseline_cutoffs": split,
                    "active_count": len(identities),
                    "identities": tuple(
                        BranchStore._freeze_lifetime_value(identity)
                        for identity in identities
                    ),
                }
            )
            continue
        if current:
            waves.append(
                BranchStore._build_lifetime_churn_regression_wave(
                    current
                )
            )
            current = []
    if current:
        waves.append(
            BranchStore._build_lifetime_churn_regression_wave(current)
        )

    if len(waves) > regression_wave_limit:
        raise ValueError(
            f"lifetime churn drift wave prediction scorecard "
            f"regression wave limit exceeded: {len(waves)} "
            f"waves, limit is {regression_wave_limit}"
        )

    split_seen: set[object] = set()
    identity_seen: set[object] = set()
    totals = {
        "splits": 0,
        "identities": 0,
        "waves": 0,
        "points": 0,
        "peak_active": 0,
    }
    for wave in waves:
        totals["waves"] += 1
        for point in wave["points"]:
            split_seen.add(point["baseline_cutoffs"])
            totals["points"] += 1
            if point["active_count"] > totals["peak_active"]:
                totals["peak_active"] = point["active_count"]
            for identity in point["identities"]:
                identity_seen.add(identity)
    totals["splits"] = len(split_seen)
    totals["identities"] = len(identity_seen)
    return {"waves": tuple(waves), "totals": totals}

@staticmethod
def _build_lifetime_churn_regression_wave(
    points: list[dict[str, object]],
) -> dict[str, object]:
    """Assemble one maximal active run into a fresh wave dict.

    Used only by
    :meth:`_build_lifetime_churn_forecast_drift_wave_prediction_scorecard_regression_waves_result`.
    The points are the run's already-built point dicts in requested
    split order; the wave keeps them as one fresh tuple.
    """
    return {
        "start_baseline_cutoffs": points[0]["baseline_cutoffs"],
        "end_baseline_cutoffs": points[-1]["baseline_cutoffs"],
        "split_count": len(points),
        "peak_regressions": max(
            point["active_count"] for point in points
        ),
        "points": tuple(points),
    }

